WITH enriched AS (SELECT id, order_id, product_id, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY quantity, id) AS row_seq, ROW_NUMBER() OVER w_ordered AS row_seq_2, AVG(unit_price) OVER (PARTITION BY order_id, product_id ORDER BY unit_price, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS unit_price_avg_2_prior, PERCENT_RANK() OVER (PARTITION BY product_id ORDER BY quantity DESC NULLS FIRST) AS quantity_percent_rank FROM order_items WINDOW w_ordered AS (PARTITION BY product_id ORDER BY quantity, id)), cleaned AS (SELECT *, GREATEST(row_seq, unit_price_avg_2_prior) AS greatest_row_seq_unit_price_avg_2_prior, COALESCE(row_seq, 0) AS row_seq_filled FROM enriched WHERE unit_price_avg_2_prior < 291), enriched_order_items AS (SELECT src.*, d.category, d.launch_date FROM cleaned src LEFT JOIN products d ON src.product_id <=> d.id WHERE d.supplier_id = 32), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY quantity_percent_rank NULLS FIRST, id) AS latest_rank FROM enriched_order_items) x WHERE latest_rank = 1), totals AS (SELECT order_id, COUNT(*) FILTER (WHERE category = 'Home') AS home_rows, PERCENTILE_APPROX(quantity_percent_rank, 0.95) AS quantity_percent_rank_p95 FROM ranked GROUP BY order_id) SELECT order_id, home_rows, quantity_percent_rank_p95 FROM totals ORDER BY order_id DESC NULLS LAST;
